//! Vendors a small, deliberately varied slice of Textual's own 448 golden
//! SVG snapshots (`tests/snapshot_tests/__snapshots__/test_snapshots/` at a
//! pinned release tag) via `svg_term`. Content-fidelity only -- Rich's SVG
//! export carries no widget-tree metadata, so these fixtures never get a
//! `truth.json` and are never scored on structural IoU.
//!
//! Five files across five different widget types, not all 448: the plan
//! calls for a parse self-check before harvesting broadly, and this list
//! *is* that self-check, kept as the initial corpus rather than thrown away.
//! Widening it to more of the 448 is future work, not a limitation of the
//! parser discovered here.

use std::path::Path;

use anyhow::{Context, Result};

use super::svg_term;

const TAG: &str = "v8.2.8";

const SAMPLES: &[(&str, &str)] = &[
    ("table", "test_auto_table"),
    ("tree", "test_example_json_tree"),
    ("progress-bar", "test_progress_bar_halfway"),
    ("list-view", "test_list_view"),
    ("log", "test_log_write"),
];

fn snapshot_url(name: &str) -> String {
    format!(
        "https://raw.githubusercontent.com/Textualize/textual/{TAG}/tests/snapshot_tests/__snapshots__/test_snapshots/{name}.svg"
    )
}

pub fn run(root: &Path) -> Result<()> {
    let dir = root.join("fixtures/vendor/textual");
    std::fs::create_dir_all(&dir)?;

    let client = reqwest::blocking::Client::new();
    for (slug, snapshot) in SAMPLES {
        let url = snapshot_url(snapshot);
        let svg = client
            .get(&url)
            .send()
            .with_context(|| format!("fetching {url}"))?
            .error_for_status()
            .with_context(|| format!("fetching {url}"))?
            .text()?;

        let grid = svg_term::parse(&svg)
            .with_context(|| format!("parsing {snapshot}.svg as a Rich terminal export"))?;
        anyhow::ensure!(
            !grid.is_blank(),
            "{snapshot}.svg parsed to an entirely blank grid -- treat as a parser bug, not a real empty screen"
        );

        let ansi = svg_term::grid_to_ansi(&grid);
        std::fs::write(dir.join(format!("{slug}.ansi")), ansi)?;
        println!(
            "wrote fixtures/vendor/textual/{slug}.ansi ({} rows x {} cols, from {snapshot}.svg @ {TAG})",
            grid.rows, grid.cols
        );
    }

    write_source_note(&dir)?;
    Ok(())
}

fn write_source_note(dir: &Path) -> Result<()> {
    let names: Vec<String> = SAMPLES
        .iter()
        .map(|(slug, snapshot)| format!("- `{slug}.ansi` <- `{snapshot}.svg`"))
        .collect();
    let note = format!(
        "Generated by `cargo run -p xtask -- vendor textual`.\n\n\
         Source: https://github.com/Textualize/textual, pinned at tag `{TAG}`,\n\
         path `tests/snapshot_tests/__snapshots__/test_snapshots/`.\n\
         License: MIT (Textualize/textual), see `LICENSE` in this directory.\n\n\
         Rich's SVG terminal export carries no widget-tree metadata, so none\n\
         of these fixtures have a `truth.json` -- they exercise round-trip\n\
         fidelity, the LLM benchmark, and human legibility only, never IoU.\n\n\
         {}\n",
        names.join("\n")
    );
    std::fs::write(dir.join("SOURCE.md"), note)?;
    Ok(())
}
